def next_permutation(perm):
    # Step1: Find the rightmost element which is smaller than its next element.
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            # Step2: Find the smallest element on the right of perm[i] which is larger than perm[i]
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap the elements
                    perm[i], perm[j] = perm[j], perm[i]
                    # Reverse the sequence after the position i
                    perm[i + 1:] = reversed(perm[i + 1:])
                    return perm
    # If no such element is found, return the list in sorted order as it is the last permutation.
    return perm[::-1]

def next_permutation(perm):
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    next_perm = list(perm)
                    next_perm[i], next_perm[j] = perm[j], perm[i]
                    next_perm[i + 1:] = reversed(next_perm[i + 1:])
                    return next_perm
    return sorted(perm)  # Return the smallest permutation if no next permutation is possible

# Example usage:
perm = [1, 2, 3]
print(next_permutation(perm))  # Output: [1, 3, 2]
